let current = 'en';
export function pickLanguage() {
  let saved = null;
  try { saved = localStorage.getItem('sundial-lang'); } catch (e) { /* storage may be blocked */ }
  if (saved && S[saved]) return saved;
  for (const l of navigator.languages || [navigator.language || 'en']) {
    const code = l.slice(0, 2).toLowerCase();
    if (S[code]) return code;
  }
  return 'en';
}
export function setLanguage(code, remember = true) {
  current = S[code] ? code : 'en';
  if (remember) { try { localStorage.setItem('sundial-lang', current); } catch (e) { /* ignore */ } }
  document.documentElement.lang = current;
  document.documentElement.dir = RTL.has(current) ? 'rtl' : 'ltr';
  document.documentElement.classList.toggle('rtl', RTL.has(current));
  applyStatic();
  document.dispatchEvent(new CustomEvent('languagechange'));
  return current;
}
export function lang() { return current; }
export function t(key, vars) {
  let s = (S[current] && S[current][key]) ?? S.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split('{' + k + '}').join(v);
  return s;
}
export function applyStatic() {
  for (const el of document.querySelectorAll('[data-i18n]')) el.innerHTML = t(el.dataset.i18n);
  for (const el of document.querySelectorAll('[data-i18n-ph]')) el.placeholder = t(el.dataset.i18nPh);
  for (const el of document.querySelectorAll('[data-i18n-title]')) el.title = t(el.dataset.i18nTitle);
  document.title = t('title');
}
export function languageSelector(container) {
  const sel = document.createElement('select');
  sel.id = 'langSel'; sel.setAttribute('aria-label', 'Language');
  for (const [code, name] of Object.entries(LANGS)) {
    const o = document.createElement('option'); o.value = code; o.textContent = name; sel.appendChild(o);
  }
  sel.value = current;
  sel.addEventListener('change', () => setLanguage(sel.value));
  container.appendChild(sel);
  return sel;
}
